class ProductCatalog:
    def __init__(self, products: Iterable[Product]):
        self.products: Dict[str, Product] = {}
        for product in products:
            self.products[normalize_sku(product.sku)] = product

    def get(self, sku: str) -> Product:
        normalized = normalize_sku(sku)
        if normalized not in self.products:
            raise KeyError(f"unknown sku {normalized}")
        return self.products[normalized]

    def list_available(self, tag: str = "") -> List[Product]:
        values = [product for product in self.products.values() if product.stock > 0]
        if tag:
            values = [product for product in values if tag in product.tags]
        return sorted(values, key=lambda product: product.sku)

    def reserve_items(self, items: List[CartItem]) -> List[Product]:
        reserved: List[Product] = []
        try:
            for item in items:
                item.validate()
                product = self.get(item.sku)
                product.reserve(item.qty)
                reserved.append(product)
            return reserved
        except Exception:
            for product, item in zip(reserved, items):
                product.release(item.qty)
            raise

    def release_items(self, items: List[CartItem]) -> None:
        for item in items:
            product = self.get(item.sku)
            product.release(item.qty)

