def build_demo_service() -> OrderService:
    catalog = ProductCatalog(
        [
            Product("BOOK-1", "Clean Architecture", 3500, 4, ["book"]),
            Product("MUG-1", "SPL Mug", 1800, 3, ["gift"]),
            Product("TEE-1", "Compiler Tee", 2500, 1, ["gift"]),
        ]
