def format_currency(cents: int) -> str:
    if cents < 0:
        raise ValueError("currency value cannot be negative")
    return f"${cents / 100:.2f}"

class NotificationService:
    def __init__(self):
        self.sent_messages: List[str] = []

    def send_receipt(self, customer: Customer, order: Order) -> str:
        message = f"Receipt for {customer.email}: order {order.order_id} total {format_currency(order.total_cents)}"
        self.sent_messages.append(message)
        return message

    def send_low_stock_alert(self, products: List[Product], threshold: int = 2) -> List[str]:
        alerts = []
        for product in products:
            if product.stock <= threshold:
                alert = f"Low stock for {product.sku}: {product.stock}"
                self.sent_messages.append(alert)
                alerts.append(alert)
        return alerts

