class PaymentGateway:
    def __init__(self, provider: str = "internal-wallet"):
        self.provider = provider
        self.authorized_total_cents = 0
        self.refunded_total_cents = 0

    def authorize(self, customer: Customer, amount_cents: int) -> PaymentReceipt:
        if amount_cents <= 0:
            raise PaymentError("amount must be positive")
        try:
            customer.debit(amount_cents)
        except ValueError as exc:
            raise PaymentError(str(exc)) from exc
        self.authorized_total_cents += amount_cents
        return PaymentReceipt(str(uuid4()), amount_cents, self.provider)

    def refund(self, customer: Customer, receipt: PaymentReceipt) -> None:
        if receipt.amount_cents <= 0:
            raise PaymentError("receipt amount must be positive")
        customer.credit(receipt.amount_cents)
        self.refunded_total_cents += receipt.amount_cents

