class PricingPolicy:
    def __init__(self, tax_rate_bps: int, coupons: Dict[str, int]):
        if tax_rate_bps < 0:
            raise ValueError("tax rate cannot be negative")
        self.tax_rate_bps = tax_rate_bps
        self.coupons = {code.upper(): value for code, value in coupons.items()}

    def quote(self, customer: Customer, items: List[CartItem], products: List[Product], coupon: str = "") -> PriceQuote:
        subtotal = self.calculate_subtotal(items, products)
        discount = self.apply_coupon(customer, subtotal, coupon)
        taxable = max(subtotal - discount, 0)
        tax = self.calculate_tax(taxable)
        total = taxable + tax
        if total <= 0:
            raise ValueError("total must be positive")
        return PriceQuote(subtotal, discount, tax, total, coupon.upper())

    def calculate_subtotal(self, items: List[CartItem], products: List[Product]) -> int:
        price_by_sku = {product.sku: product.price_cents for product in products}
        subtotal = 0
        for item in items:
            if item.qty <= 0:
                raise ValueError("qty must be positive")
            price = price_by_sku[item.sku.upper()]
            if price <= 0:
                raise ValueError("price_cents must be positive")
            subtotal += price * item.qty
        return subtotal

    def apply_coupon(self, customer: Customer, subtotal_cents: int, coupon: str = "") -> int:
        if not coupon:
            return 0
        code = coupon.upper()
        if code not in self.coupons:
            raise ValueError("coupon is not supported")
        discount = self.coupons[code]
        if customer.tier == "vip":
            discount += 500
        return min(discount, subtotal_cents)

    def calculate_tax(self, taxable_cents: int) -> int:
        if taxable_cents < 0:
            raise ValueError("taxable amount cannot be negative")
        return taxable_cents * self.tax_rate_bps // 10000

